create extension if not exists pgcrypto;
create type channel_status as enum ('draft','published','blocked');
create type rights_status as enum ('pending','confirmed','expired','blocked');
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, locale text not null default 'uz', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists providers (id uuid primary key default gen_random_uuid(), name text not null, kind text not null, status text not null default 'draft', secret_ref text, created_at timestamptz not null default now());
create table if not exists categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null);
create table if not exists channels (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, country text not null default 'INT', language text not null default 'ru', category_id uuid references categories(id), status channel_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists channel_variants (id uuid primary key default gen_random_uuid(), channel_id uuid not null references channels(id) on delete cascade, external_id text, quality text not null default 'SD', timeshift text, provider_id uuid references providers(id), unique(channel_id, provider_id, quality, timeshift));
create table if not exists content_rights (id uuid primary key default gen_random_uuid(), provider_id uuid not null references providers(id) on delete cascade, rights_type text not null, territories text[] not null default '{}', starts_at timestamptz, ends_at timestamptz, document_ref text, status rights_status not null default 'pending', admin_notes text);
create table if not exists favorites (user_id uuid references auth.users(id) on delete cascade, channel_id uuid references channels(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id, channel_id));
create table if not exists watch_history (user_id uuid references auth.users(id) on delete cascade, channel_id uuid references channels(id) on delete cascade, watched_at timestamptz not null default now(), seconds_watched integer not null default 0, primary key(user_id, channel_id));
create table if not exists imports (id uuid primary key default gen_random_uuid(), provider_id uuid references providers(id), status text not null default 'preview', total integer not null default 0, accepted integer not null default 0, rejected integer not null default 0, created_at timestamptz not null default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists channels_country_status_idx on channels(country, status); create index if not exists variants_channel_idx on channel_variants(channel_id); create index if not exists history_user_time_idx on watch_history(user_id, watched_at desc);
alter table profiles enable row level security; alter table favorites enable row level security; alter table watch_history enable row level security;
create policy profiles_self on profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy favorites_self on favorites for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy history_self on watch_history for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
